async function renderFitnessReportCanvas() {
  const width = 1240;
  const model = buildFitnessReportModel();
  const height = getFitnessReportExportHeight(model);
  const html = `
    <div xmlns="http://www.w3.org/1999/xhtml">
      <style>${getFitnessReportExportCss(height)}</style>
      ${renderFitnessReportTemplate(model)}
    </div>
  `;
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
      <foreignObject width="${width}" height="${height}">${html}</foreignObject>
    </svg>
  `;
  if (document.fonts?.ready) await document.fonts.ready;
  const svgBlob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(svgBlob);
  try {
    const image = new Image();
    image.decoding = "async";
    image.src = url;
    await new Promise((resolve, reject) => {
      image.onload = resolve;
      image.onerror = reject;
    });
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#fffefa";
    ctx.fillRect(0, 0, width, height);
    ctx.drawImage(image, 0, 0);
    return canvas;
  } finally {
    URL.revokeObjectURL(url);
  }
}

function canvasToBlob(canvas, type = "image/png", quality) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("보고서 이미지 생성에 실패했습니다."));
    }, type, quality);
  });
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Mobile browsers can start the download after the click handler returns.
  // Keep the object URL alive long enough for Safari/Android download managers.
  window.setTimeout(() => URL.revokeObjectURL(url), 30000);
}

function isIOSLikeDevice() {
  return /iPad|iPhone|iPod/i.test(navigator.userAgent || "")
    || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}

function createShareFile(blob, filename) {
  if (typeof File !== "function") return null;
  return new File([blob], filename, { type: blob.type || "application/octet-stream" });
}

async function saveReportImageFile(canvas, filename, type = "image/jpeg") {
  const blob = await canvasToBlob(canvas, type, type === "image/jpeg" ? 0.94 : undefined);
  const file = createShareFile(blob, filename);
  // iOS does not consistently place a downloaded JPEG in Photos. Opening the
  // native share sheet lets the employee choose "Save Image" reliably.
  if (isIOSLikeDevice() && file && navigator.share && navigator.canShare?.({ files: [file] })) {
    await navigator.share({ title: filename.replace(/\.(jpe?g|png)$/i, ""), files: [file] });
    showAppToast("공유창에서 ‘이미지 저장’을 선택하세요");
    return;
  }
  downloadBlob(blob, filename);
  showAppToast(type === "image/png" ? "보고서 PNG를 저장했습니다" : "보고서 사진을 저장했습니다");
}

async function saveReportPhoto(canvas, filename) {
  return saveReportImageFile(canvas, filename, "image/jpeg");
}

async function saveReportPng(canvas, filename) {
  return saveReportImageFile(canvas, filename, "image/png");
}

async function shareReportArtifacts({ canvas, base, title, text }) {
  const jpegBlob = await canvasToBlob(canvas, "image/jpeg", 0.94);
  const pdfBlob = createPdfBlobFromCanvas(canvas);
  const jpegFile = createShareFile(jpegBlob, `${base}.jpg`);
  const pdfFile = createShareFile(pdfBlob, `${base}.pdf`);
  const files = [jpegFile, pdfFile].filter(Boolean);
  if (files.length && navigator.share && navigator.canShare?.({ files })) {
    await navigator.share({ title, text, files });
    return;
  }
  if (jpegFile && navigator.share && navigator.canShare?.({ files: [jpegFile] })) {
    await navigator.share({ title, text, files: [jpegFile] });
    return;
  }
  if (navigator.share) {
    await navigator.share({ title, text });
    return;
  }
  await navigator.clipboard?.writeText(text);
  showAppToast("공유를 지원하지 않아 보고서 내용을 복사했습니다");
}

function splitReportCanvasIntoA4Pages(canvas) {
  const pageRatio = 297 / 210;
  const sourcePageHeight = Math.max(1, Math.round(canvas.width * pageRatio));
  const pages = [];
  for (let sourceY = 0; sourceY < canvas.height; sourceY += sourcePageHeight) {
    const sourceHeight = Math.min(sourcePageHeight, canvas.height - sourceY);
    const page = document.createElement("canvas");
    page.width = canvas.width;
    page.height = sourcePageHeight;
    const context = page.getContext("2d");
    context.fillStyle = "#ffffff";
    context.fillRect(0, 0, page.width, page.height);
    context.drawImage(canvas, 0, sourceY, canvas.width, sourceHeight, 0, 0, canvas.width, sourceHeight);
    pages.push(page);
  }
  return pages.length ? pages : [canvas];
}

async function printReportCanvas(canvas, title = "Daily Report") {
  const pageBlobs = await Promise.all(splitReportCanvasIntoA4Pages(canvas)
    .map((page) => canvasToBlob(page, "image/jpeg", 0.96)));
  const imageUrls = pageBlobs.map((blob) => URL.createObjectURL(blob));
  const frame = document.createElement("iframe");
  frame.title = `${title} 인쇄 전용 문서`;
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;right:100%;bottom:0;width:1px;height:1px;border:0;opacity:0;pointer-events:none";
  document.body.appendChild(frame);
  const cleanup = () => {
    imageUrls.forEach((url) => URL.revokeObjectURL(url));
    frame.remove();
  };
  const printDocument = frame.contentDocument;
  printDocument.open();
  printDocument.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>@page{size:A4 portrait;margin:0}html,body{margin:0;padding:0;background:#fff}.report-print-page{width:210mm;height:297mm;break-after:page;page-break-after:always;overflow:hidden}.report-print-page:last-child{break-after:auto;page-break-after:auto}img{display:block;width:210mm;height:297mm;object-fit:contain;object-position:top center}</style></head><body>${imageUrls.map((url, index) => `<section class="report-print-page"><img alt="${escapeHtml(title)} ${index + 1}쪽" src="${url}"></section>`).join("")}</body></html>`);
  printDocument.close();
  const images = [...printDocument.querySelectorAll("img")];
  await Promise.all(images.map((image) => new Promise((resolve, reject) => {
    if (image.complete && image.naturalWidth) return resolve();
    image.addEventListener("load", resolve, { once: true });
    image.addEventListener("error", () => reject(new Error("인쇄용 보고서 이미지를 준비하지 못했습니다.")), { once: true });
  })));
  const printWindow = frame.contentWindow;
  printWindow.addEventListener("afterprint", cleanup, { once: true });
  printWindow.focus();
  printWindow.print();
  window.setTimeout(cleanup, 60000);
}

function concatUint8Arrays(parts) {
  const total = parts.reduce((sum, part) => sum + part.length, 0);
  const merged = new Uint8Array(total);
  let offset = 0;
  parts.forEach((part) => {
    merged.set(part, offset);
    offset += part.length;
  });
  return merged;
}

function dataUrlToUint8Array(dataUrl) {
  const base64 = String(dataUrl).split(",")[1] || "";
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function createPdfBlobFromCanvas(canvas) {
  const encoder = new TextEncoder();
  const pages = splitReportCanvasIntoA4Pages(canvas);
  const pageWidth = 595.28;
  const pageHeight = 841.89;
  const content = `q\n${pageWidth} 0 0 ${pageHeight} 0 0 cm\n/Im0 Do\nQ`;
  const pageObjectIds = pages.map((_, index) => 3 + index * 3);
  const objects = [
    encoder.encode("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"),
    encoder.encode(`2 0 obj\n<< /Type /Pages /Kids [${pageObjectIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} >>\nendobj\n`),
  ];
  pages.forEach((page, index) => {
    const pageObjectId = pageObjectIds[index];
    const contentObjectId = pageObjectId + 1;
    const imageObjectId = pageObjectId + 2;
    const jpegBytes = dataUrlToUint8Array(page.toDataURL("image/jpeg", 0.92));
    objects.push(
      encoder.encode(`${pageObjectId} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /XObject << /Im0 ${imageObjectId} 0 R >> >> /Contents ${contentObjectId} 0 R >>\nendobj\n`),
      encoder.encode(`${contentObjectId} 0 obj\n<< /Length ${content.length} >>\nstream\n${content}\nendstream\nendobj\n`),
      concatUint8Arrays([
        encoder.encode(`${imageObjectId} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${page.width} /Height ${page.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpegBytes.length} >>\nstream\n`),
        jpegBytes,
        encoder.encode("\nendstream\nendobj\n"),
      ]),
    );
  });
  const chunks = [encoder.encode("%PDF-1.4\n%\n")];
  const offsets = [0];
  let length = chunks[0].length;
  objects.forEach((object) => {
    offsets.push(length);
    chunks.push(object);
    length += object.length;
  });
  const xrefStart = length;
  const xref = [
    "xref",
    `0 ${objects.length + 1}`,
    "0000000000 65535 f ",
    ...offsets.slice(1).map((offset) => `${String(offset).padStart(10, "0")} 00000 n `),
    "trailer",
    `<< /Size ${objects.length + 1} /Root 1 0 R >>`,
    "startxref",
    String(xrefStart),
    "%%EOF",
  ].join("\n");
  chunks.push(encoder.encode(xref));
  return new Blob(chunks, { type: "application/pdf" });
}

async function saveFitnessReportImage() {
  const canvas = await renderFitnessReportCanvas();
  await saveReportPhoto(canvas, `${getFitnessReportFileBase()}.jpg`);
}

async function saveFitnessReportPng() {
  const canvas = await renderFitnessReportCanvas();
  await saveReportPng(canvas, `${getFitnessReportFileBase()}.png`);
}

async function saveFitnessReportPdf() {
  const pdf = createPdfBlobFromCanvas(await renderFitnessReportCanvas());
  downloadBlob(pdf, `${getFitnessReportFileBase()}.pdf`);
  showAppToast("A4 PDF 보고서를 저장했습니다");
}

async function shareFitnessReport() {
  const canvas = await renderFitnessReportCanvas();
  const base = getFitnessReportFileBase();
  const text = buildFitnessReportLines().join("\n");
  await shareReportArtifacts({
    canvas,
    base,
    title: "Beyond Fitness Report",
    text,
  });
}

function switchView(view, options = {}) {
  if (!state) {
    window.setTimeout(() => switchView(view, options), 0);
    return;
  }
  const requestedView = view;
  if (view === "management") view = "control";
  if (isExplicitlySignedOut() && view !== "auth") {
    view = "auth";
    renderAuthStatus("로그아웃되었습니다. 다시 사용하려면 로그인 또는 직원등록을 진행해주세요.");
  }
  if (!["auth", "settings"].includes(view) && authState.user && !isProfileApproved()) {
    view = "auth";
    renderAuthStatus(`현재 상태: ${getApprovalStatusLabel()}. 승인 후 업무일지를 사용할 수 있습니다.`);
  }
  if (view === "attendance" && !canOpenLaborSection()) {
    view = getUserWorklogView();
  }
  if (view === "staff" && !canAccessStaffSection()) view = getUserWorklogView();
  if (view === "control" && !canAccessControlTower()) view = getUserWorklogView();
  if (view === "executive" && !(isRepresentativeProfile() || hasProfilePermission("executiveRoom"))) view = getUserWorklogView();
  if (view === "premium" && !canAccessPremiumOperations()) view = getUserWorklogView();
  if (view === "worklog") view = getUserWorklogView();
  view = view === "today" ? "bangju-log" : view;
  if (view !== "fitness-log" && fitnessMobileFocusMode !== "split") resetFitnessMobileFocusToSplit({ blur: true });
  ensureSelectedEmployeeForWorklogView(view);
  activeView = view;
  document.body.dataset.activeView = view;
  if (shouldHydrateRepresentativeControlForView(view)) {
    void hydrateRepresentativeControlData(getActiveDateKey());
  }
  renderResponsiveMode();
  closeMainMenuPopover();
  closeGlobalCommandPalette();
  const primaryView = getPrimaryNavigationView(view);
  document.querySelectorAll(".worklog-tabs button").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.view === primaryView);
  });
  const panelView = worklogViewAliases[view] || view;
  document.querySelectorAll(".worklog-view").forEach((panel) => panel.classList.toggle("is-active", panel.id === `view-${panelView}`));
  dockGlobalHeaderActions(panelView);
  const menuSelect = document.getElementById("mainMenuWheelSelect");
  if (menuSelect) {
    const menuValue = getPrimaryNavigationView(requestedView === "worklog" ? "worklog" : view);
    if (menuValue && menuSelect.value !== menuValue) menuSelect.value = menuValue;
  }
  renderEmployeeTitle();
  renderDateNav();
  renderGlobalEmployeeIdentity();
  renderOsDashboard();
  renderExecutiveManagement();
  renderControlTower();
  renderWorklogOverview();
  renderAiCoach();
  renderPremiumOperatingSystem();
  renderFitnessDashboard();
  renderEntries();
  renderStaffMaster();
  if (view === "staff" && canAccessStaffSection() && !authState.approvalRowsLoaded) refreshStaffApprovalRows();
  renderAttendance();
  renderOrganization();
  updateGlobalAttendanceVisibility(view);
  dockGlobalHeaderActions(panelView);
  applyCurrentWorklogPermissionState(view);
  if (view === "fitness-log") window.setTimeout(() => showFitnessPageToast(), 80);
  if (!options.skipRemoteRefresh) scheduleActiveWorklogRefresh();
}

function getActiveViewPanel(panelView = worklogViewAliases[activeView] || activeView) {
  return document.getElementById(`view-${panelView}`) || document.querySelector(".worklog-view.is-active");
}

function dockGlobalHeaderActions(panelView = worklogViewAliases[activeView] || activeView) {
  const panel = getActiveViewPanel(panelView);
  const menuButton = document.getElementById("settingsGearButton");
  const commandButton = document.getElementById("globalCommandButton");
  const menuPopover = document.getElementById("mainMenuPopover");
  if (!panel || !menuButton || !menuPopover) return;

  if (panelView === "executive" || panelView === "control") {
    const actions = panelView === "executive"
      ? document.querySelector(".executive-hero-actions")
      : document.querySelector(".control-tower-hero-actions");
    if (actions && commandButton) actions.appendChild(commandButton);
    if (actions && menuPopover.parentElement !== actions) actions.appendChild(menuPopover);
    return;
  }

  if (panelView === "worklog-overview") {
    const overviewDateNav = document.getElementById("overviewDateSwipeArea");
    if (overviewDateNav) {
      if (commandButton) overviewDateNav.appendChild(commandButton);
      overviewDateNav.appendChild(menuButton);
      overviewDateNav.appendChild(menuPopover);
    }
    return;
  }

  const target = panelView === "attendance" ? panel.querySelector(".work-history-hero") || panel : panel;
  let dock = target.querySelector(":scope > .section-menu-dock") || panel.querySelector(":scope > .section-menu-dock");
  if (!dock) {
    dock = document.createElement("div");
    dock.className = "section-menu-dock";
    dock.setAttribute("aria-label", "현재 섹션 메뉴");
  }
  if (dock.parentElement !== target) {
    target.prepend(dock);
  }

  const modeButton = document.getElementById("globalViewModeButton");
  const attendanceButton = document.getElementById("globalAttendanceButton");
  const attendancePopover = document.getElementById("attendancePopover");
  const approvalButton = document.getElementById("approvalAlertButton");

  if (approvalButton && !approvalButton.hidden) dock.appendChild(approvalButton);
  if (modeButton && !modeButton.hidden) dock.appendChild(modeButton);
  if (attendanceButton && !attendanceButton.hidden) dock.appendChild(attendanceButton);
  if (commandButton) dock.appendChild(commandButton);
  dock.appendChild(menuButton);
  dock.appendChild(menuPopover);
  if (attendancePopover) dock.appendChild(attendancePopover);
}

function dockMainMenuPopoverToTrigger(trigger = null) {
  const popover = document.getElementById("mainMenuPopover");
  if (!popover || !trigger) return;

  const host = trigger.closest(
    ".section-menu-dock, .executive-hero-actions, .control-tower-hero-actions, .overview-date-nav"
  );
  if (host && popover.parentElement !== host) host.appendChild(popover);
}

function toggleMainMenuPopover(trigger = null) {
  const popover = document.getElementById("mainMenuPopover");
  const button = document.getElementById("settingsGearButton");
  const executiveButton = document.getElementById("executiveMenuButton");
  const controlButton = document.getElementById("controlTowerMenuButton");
  if (!popover) return;
  dockMainMenuPopoverToTrigger(trigger);
  const willOpen = popover.hidden;
  if (willOpen) renderMainMenuAuthButton();
  popover.hidden = !willOpen;
  button?.setAttribute("aria-expanded", String(willOpen));
  executiveButton?.setAttribute("aria-expanded", String(willOpen));
  controlButton?.setAttribute("aria-expanded", String(willOpen));
  if (willOpen) {
    closeAttendancePopover();
    if (isRepresentativeProfile()) void hydrateRepresentativeControlData(getActiveDateKey());
  }
  if (willOpen) popover.querySelector("button:not([hidden])")?.focus();
}

function closeMainMenuPopover() {
  const popover = document.getElementById("mainMenuPopover");
  const button = document.getElementById("settingsGearButton");
  const executiveButton = document.getElementById("executiveMenuButton");
  const controlButton = document.getElementById("controlTowerMenuButton");
  if (!popover || popover.hidden) return;
  popover.hidden = true;
  button?.setAttribute("aria-expanded", "false");
  executiveButton?.setAttribute("aria-expanded", "false");
  controlButton?.setAttribute("aria-expanded", "false");
}

